Minimal FastMCP tool pattern used throughout this project:
@mcp.tool()
async def my_tool(arg: str, confirm: bool = False) -> str:
    """One-line description the model reads to decide when to call this."""
    if is_destructive and not confirm:
        return "REFUSED: pass confirm=true to proceed."
    try:
        result = await do_the_thing(arg)
        return f"OK: {result}"
    except ExpectedFailureType as e:
        return f"ERROR: {e}"

